-- Ejecutar en Supabase -> SQL Editor -> New query -> Run.
-- Requiere 01_esquema.sql.
--
-- Armas de Genshin Impact: 246. Con stats, efecto por nivel, como
-- conseguirlas, materiales y personajes recomendados (guias de Game8).
--
-- Los datos son una copia de la base de datos tal y como estaba el 2026-09-15.
-- Inserta lo que falte y actualiza lo que ya exista, sin borrar nada: los
-- favoritos, tier lists y guias de los usuarios que apuntan a estas filas se
-- conservan. Ojo: si has cambiado algo desde la app despues de esa fecha,
-- ejecutarlo lo devuelve a como estaba en la copia.
--
-- Estas armas no estaban en la copia de la base de datos (genshin_armas.sql no
-- llego a ejecutarse), asi que salen de los archivos: datos de Yatta y
-- recomendados de Game8.

--
-- PARTE 2 de 4 (70 filas). El archivo entero no cabia en el SQL Editor:
-- ejecuta las 4 partes, en cualquier orden.

insert into public.weapons (
  id, game_id, name, name_en, rarity, category, image_url, description, base_hp, base_atk, base_def, sub_stat_name, sub_stat_value, passive_name, passive_levels, how_to_get, ascension, good_for, recommended
)
values
  ('gi-w-15503', 'genshin-impact', 'Elegía del Fin', 'Elegy for the End', '5', 'Arco', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Bow_Widsith.png', 'Un arco tan bello como el instrumento de un bardo. Las flechas que dispara son como un suspiro capaz de atravesar el corazón de una persona.', null, 608, null, 'Recarga de Energía', '55,1%', 'Canción de despedida', '["Una parte del «Gran concierto milenario» que flota por los vientos. Aumenta en 60 pts. la Maestría Elemental. Cuando el personaje que lleva esta arma equipada ataca a un enemigo con una Habilidad Elemental o Definitiva, dicho personaje obtiene un talismán de reminiscencia que puede adquirirse una vez cada 0.2 s como máximo. Este efecto también puede ocurrir cuando el personaje que lleva equipada esta arma está en tu equipo pero no en uso. Al obtener 4 talismanes de reminiscencia, estos se consumirán y otorgarán a todos los miembros del equipo cercanos el efecto de «Gran concierto milenario: Canción del adiós» durante 12 s, el cual aumenta en 100 pts. la Maestría Elemental y el ATQ en un 20%. Tras activarse este efecto, no podrán obtenerse talismanes de reminiscencia durante 20 s. Los efectos de «Gran concierto milenario» no se acumularán con otros efectos del mismo tipo.","Una parte del «Gran concierto milenario» que flota por los vientos. Aumenta en 75 pts. la Maestría Elemental. Cuando el personaje que lleva esta arma equipada ataca a un enemigo con una Habilidad Elemental o Definitiva, dicho personaje obtiene un talismán de reminiscencia que puede adquirirse una vez cada 0.2 s como máximo. Este efecto también puede ocurrir cuando el personaje que lleva equipada esta arma está en tu equipo pero no en uso. Al obtener 4 talismanes de reminiscencia, estos se consumirán y otorgarán a todos los miembros del equipo cercanos el efecto de «Gran concierto milenario: Canción del adiós» durante 12 s, el cual aumenta en 125 pts. la Maestría Elemental y el ATQ en un 25%. Tras activarse este efecto, no podrán obtenerse talismanes de reminiscencia durante 20 s. Los efectos de «Gran concierto milenario» no se acumularán con otros efectos del mismo tipo.","Una parte del «Gran concierto milenario» que flota por los vientos. Aumenta en 90 pts. la Maestría Elemental. Cuando el personaje que lleva esta arma equipada ataca a un enemigo con una Habilidad Elemental o Definitiva, dicho personaje obtiene un talismán de reminiscencia que puede adquirirse una vez cada 0.2 s como máximo. Este efecto también puede ocurrir cuando el personaje que lleva equipada esta arma está en tu equipo pero no en uso. Al obtener 4 talismanes de reminiscencia, estos se consumirán y otorgarán a todos los miembros del equipo cercanos el efecto de «Gran concierto milenario: Canción del adiós» durante 12 s, el cual aumenta en 150 pts. la Maestría Elemental y el ATQ en un 30%. Tras activarse este efecto, no podrán obtenerse talismanes de reminiscencia durante 20 s. Los efectos de «Gran concierto milenario» no se acumularán con otros efectos del mismo tipo.","Una parte del «Gran concierto milenario» que flota por los vientos. Aumenta en 105 pts. la Maestría Elemental. Cuando el personaje que lleva esta arma equipada ataca a un enemigo con una Habilidad Elemental o Definitiva, dicho personaje obtiene un talismán de reminiscencia que puede adquirirse una vez cada 0.2 s como máximo. Este efecto también puede ocurrir cuando el personaje que lleva equipada esta arma esté en tu equipo pero no en uso. Al obtener 4 talismanes de reminiscencia, estos se consumirán y otorgarán a todos los miembros del equipo cercanos el efecto de «Gran concierto milenario: Canción del adiós» durante 12 s, el cual aumenta en 175 pts. la Maestría Elemental y el ATQ en un 35%. Tras activarse este efecto, no podrán obtenerse talismanes de reminiscencia durante 20 s. Los efectos de «Gran concierto milenario» no se acumularán con otros efectos del mismo tipo.","Una parte del «Gran concierto milenario» que flota por los vientos. Aumenta en 120 pts. la Maestría Elemental. Cuando el personaje que lleva esta arma equipada ataca a un enemigo con una Habilidad Elemental o Definitiva, dicho personaje obtiene un talismán de reminiscencia que puede adquirirse una vez cada 0.2 s como máximo. Este efecto también puede ocurrir cuando el personaje que lleva equipada esta arma está en tu equipo pero no en uso. Al obtener 4 talismanes de reminiscencia, estos se consumirán y otorgarán a todos los miembros del equipo cercanos el efecto de «Gran concierto milenario: Canción del adiós» durante 12 s, el cual aumenta en 200 pts. la Maestría Elemental y el ATQ en un 40%. Tras activarse este efecto, no podrán obtenerse talismanes de reminiscencia durante 20 s. Los efectos de «Gran concierto milenario» no se acumularán con otros efectos del mismo tipo."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","cantidad":5},{"nombre":"Insignia del recluta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112032.png","cantidad":3},{"nombre":"Diente de leche de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114005.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","cantidad":18},{"nombre":"Insignia del recluta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112032.png","cantidad":12},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114006.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","cantidad":9},{"nombre":"Insignia del sargento","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112033.png","cantidad":9},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114006.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","cantidad":18},{"nombre":"Insignia del sargento","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112033.png","cantidad":14},{"nombre":"Colmillo roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114007.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","cantidad":14},{"nombre":"Insignia del oficial","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112034.png","cantidad":9},{"nombre":"Colmillo roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114007.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Cuerno con cristal negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112016.png","cantidad":27},{"nombre":"Insignia del oficial","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112034.png","cantidad":18},{"nombre":"Nostalgia del lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114008.png","cantidad":6}]}]'::jsonb, 'Venti (Arconte Anemo), Yelan, Amber, Collei, Diona, Faruzán, Fischl, Gorou y Kujou Sara.', '[{"id":"gi-venti","grupo":"lista"},{"id":"gi-yelan","grupo":"lista"},{"id":"gi-amber","grupo":"lista"},{"id":"gi-collei","grupo":"lista"},{"id":"gi-diona","grupo":"lista"},{"id":"gi-faruzan","grupo":"lista"},{"id":"gi-fischl","grupo":"lista"},{"id":"gi-gorou","grupo":"lista"},{"id":"gi-kujou-sara","grupo":"lista"}]'::jsonb),
  ('gi-w-13513', 'genshin-impact', 'Elegía Lumidulce', 'Lumidouce Elegy', '5', 'Lanza', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Pole_Muguet.png', 'Una magnífica lanza decorada con cristales azulados. Dicen que era el arma más preciada de cierta verduga del justiciazgo legendaria, aunque ella nunca llegó a usarla.', null, 608, null, 'Prob. CRIT', '33,1%', 'Obertura del alba', '["El ATQ aumenta en un 15%. Cuando el portador de esta arma causa una reacción de Quemadura contra un enemigo o tras infligir Daño Dendro a un enemigo quemado, el daño infligido aumenta en un 18%. Este efecto dura 8 s y puede acumularse hasta 2 veces. Al alcanzar 2 acumulaciones o cuando la duración de estas se reinicia, restaura 12 pts. de Energía Elemental. Solo se puede restaurar Energía Elemental una vez cada 12 s de esta manera. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso.","El ATQ aumenta en un 19%. Cuando el portador de esta arma causa una reacción de Quemadura contra un enemigo o tras infligir Daño Dendro a un enemigo quemado, el daño infligido aumenta en un 23%. Este efecto dura 8 s y puede acumularse hasta 2 veces. Al alcanzar 2 acumulaciones o cuando la duración de estas se reinicia, restaura 13 pts. de Energía Elemental. Solo se puede restaurar Energía Elemental una vez cada 12 s de esta manera. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso.","El ATQ aumenta en un 23%. Cuando el portador de esta arma causa una reacción de Quemadura contra un enemigo o tras infligir Daño Dendro a un enemigo quemado, el daño infligido aumenta en un 28%. Este efecto dura 8 s y puede acumularse hasta 2 veces. Al alcanzar 2 acumulaciones o cuando la duración de estas se reinicia, restaura 14 pts. de Energía Elemental. Solo se puede restaurar Energía Elemental una vez cada 12 s de esta manera. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso.","El ATQ aumenta en un 27%. Cuando el portador de esta arma causa una reacción de Quemadura contra un enemigo o tras infligir Daño Dendro a un enemigo quemado, el daño infligido aumenta en un 33%. Este efecto dura 8 s y puede acumularse hasta 2 veces. Al alcanzar 2 acumulaciones o cuando la duración de estas se reinicia, restaura 15 pts. de Energía Elemental. Solo se puede restaurar Energía Elemental una vez cada 12 s de esta manera. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso.","El ATQ aumenta en un 31%. Cuando el portador de esta arma causa una reacción de Quemadura contra un enemigo o tras infligir Daño Dendro a un enemigo quemado, el daño infligido aumenta en un 38%. Este efecto dura 8 s y puede acumularse hasta 2 veces. Al alcanzar 2 acumulaciones o cuando la duración de estas se reinicia, restaura 16 pts. de Energía Elemental. Solo se puede restaurar Energía Elemental una vez cada 12 s de esta manera. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Néctar de Megaflora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112038.png","cantidad":3},{"nombre":"Empuñadura destrozada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112098.png","cantidad":5},{"nombre":"Copa rota del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114057.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Néctar de Megaflora","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112038.png","cantidad":12},{"nombre":"Empuñadura destrozada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112098.png","cantidad":18},{"nombre":"Copa de vino del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114058.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Néctar brillante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112039.png","cantidad":9},{"nombre":"Empuñadura hendida","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112099.png","cantidad":9},{"nombre":"Copa de vino del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114058.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Néctar brillante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112039.png","cantidad":14},{"nombre":"Empuñadura hendida","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112099.png","cantidad":18},{"nombre":"Copa de plata del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114059.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Néctar energético","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112040.png","cantidad":9},{"nombre":"Empuñadura imperecedera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112100.png","cantidad":14},{"nombre":"Copa de plata del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114059.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Néctar energético","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112040.png","cantidad":18},{"nombre":"Empuñadura imperecedera","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112100.png","cantidad":27},{"nombre":"Copa de oro del mar impoluto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114060.png","cantidad":6}]}]'::jsonb, 'Emilie y Xiangling.', '[{"id":"gi-emilie","grupo":"lista"},{"id":"gi-xiangling","grupo":"lista"}]'::jsonb),
  ('gi-w-12511', 'genshin-impact', 'Emblema del Mar de Juncos', 'Beacon of the Reed Sea', '5', 'Mandoble', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Claymore_Deshret.png', 'Un mandoble de factura antigua con la punta semicircular. Parece que era un arma usada antaño por la realeza para ciertas ceremonias.', null, 608, null, 'Prob. CRIT', '33,1%', 'Vigía del mar de arena', '["Tras golpear a un enemigo con una Habilidad Elemental, el ATQ aumenta en un 20% durante 8 s. Asimismo, cuando el personaje recibe daño, su ATQ aumenta en un 20% durante 8 s. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso. Además, si el portador de esta arma no está bajo la protección de un escudo, su Vida Máx. aumenta en un 32%.","Tras golpear a un enemigo con una Habilidad Elemental, el ATQ aumenta en un 25% durante 8 s. Asimismo, cuando el personaje recibe daño, su ATQ aumenta en un 25% durante 8 s. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso. Además, si el portador de esta arma no está bajo la protección de un escudo, su Vida Máx. aumenta en un 40%.","Tras golpear a un enemigo con una Habilidad Elemental, el ATQ aumenta en un 30% durante 8 s. Asimismo, cuando el personaje recibe daño, su ATQ aumenta en un 30% durante 8 s. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso. Además, si el portador de esta arma no está bajo la protección de un escudo, su Vida Máx. aumenta en un 48%.","Tras golpear a un enemigo con una Habilidad Elemental, el ATQ aumenta en un 35% durante 8 s. Asimismo, cuando el personaje recibe daño, su ATQ aumenta en un 35% durante 8 s. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso. Además, si el portador de esta arma no está bajo la protección de un escudo, su Vida Máx. aumenta en un 56%.","Tras golpear a un enemigo con una Habilidad Elemental, el ATQ aumenta en un 40% durante 8 s. Asimismo, cuando el personaje recibe daño, su ATQ aumenta en un 40% durante 8 s. Estos dos efectos se pueden activar incluso cuando el personaje está en tu equipo pero no en uso. Además, si el portador de esta arma no está bajo la protección de un escudo, su Vida Máx. aumenta en un 64%."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Satén rojo descolorido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112065.png","cantidad":3},{"nombre":"Caparazón desfigurado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112074.png","cantidad":5},{"nombre":"Eco del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114045.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Satén rojo descolorido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112065.png","cantidad":12},{"nombre":"Caparazón desfigurado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112074.png","cantidad":18},{"nombre":"Resplandor del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114046.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Seda roja bordada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112066.png","cantidad":9},{"nombre":"Caparazón sólido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112075.png","cantidad":9},{"nombre":"Resplandor del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114046.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Seda roja bordada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112066.png","cantidad":14},{"nombre":"Caparazón sólido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112075.png","cantidad":18},{"nombre":"Sueño del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114047.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Brocado rojo lujoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112067.png","cantidad":9},{"nombre":"Caparazón grabado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112076.png","cantidad":14},{"nombre":"Sueño del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114047.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Brocado rojo lujoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112067.png","cantidad":18},{"nombre":"Caparazón grabado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112076.png","cantidad":27},{"nombre":"Pasado del poder del sol","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114048.png","cantidad":6}]}]'::jsonb, 'Mavuika (Arconte Pyro), Kinich, Navia, Dehya, Eula, Diluc, Gaming, Fréminet, Kaveh, Dori, Sayu, Xinyan, Chongyun, Beidou, Noelle y Razor.', '[{"id":"gi-mavuika","grupo":"lista"},{"id":"gi-kinich","grupo":"lista"},{"id":"gi-navia","grupo":"lista"},{"id":"gi-dehya","grupo":"lista"},{"id":"gi-eula","grupo":"lista"},{"id":"gi-diluc","grupo":"lista"},{"id":"gi-gaming","grupo":"lista"},{"id":"gi-freminet","grupo":"lista"},{"id":"gi-kaveh","grupo":"lista"},{"id":"gi-dori","grupo":"lista"},{"id":"gi-sayu","grupo":"lista"},{"id":"gi-xinyan","grupo":"lista"},{"id":"gi-chongyun","grupo":"lista"},{"id":"gi-beidou","grupo":"lista"},{"id":"gi-noelle","grupo":"lista"},{"id":"gi-razor","grupo":"lista"}]'::jsonb),
  ('gi-w-14434', 'genshin-impact', 'Escarcha del Albor', 'Dawning Frost', '4', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_Ziedas.png', 'Un objeto ritual plateado, puro e impoluto. Dicen que se trataba de una reliquia heredada de generación en generación entre las damas del Lejano Norte.', null, 510, null, 'Daño CRIT', '55,1%', 'Sueños nocturnos', '["Tras golpear a un enemigo con un Ataque Cargado, la Maestría Elemental aumenta en 72 pts. durante 10 s. Tras golpear a un enemigo con una Habilidad Elemental, la Maestría Elemental aumenta en 48 pts. durante 10 s.","Tras golpear a un enemigo con un Ataque Cargado, la Maestría Elemental aumenta en 90 pts. durante 10 s. Tras golpear a un enemigo con una Habilidad Elemental, la Maestría Elemental aumenta en 60 pts. durante 10 s.","Tras golpear a un enemigo con un Ataque Cargado, la Maestría Elemental aumenta en 108 pts. durante 10 s. Tras golpear a un enemigo con una Habilidad Elemental, la Maestría Elemental aumenta en 72 pts. durante 10 s.","Tras golpear a un enemigo con un Ataque Cargado, la Maestría Elemental aumenta en 126 pts. durante 10 s. Tras golpear a un enemigo con una Habilidad Elemental, la Maestría Elemental aumenta en 84 pts. durante 10 s.","Tras golpear a un enemigo con un Ataque Cargado, la Maestría Elemental aumenta en 144 pts. durante 10 s. Tras golpear a un enemigo con una Habilidad Elemental, la Maestría Elemental aumenta en 96 pts. durante 10 s."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Distintivo desgastado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112125.png","cantidad":2},{"nombre":"Destello de la noche escarchada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112128.png","cantidad":3},{"nombre":"Fragmento del instrumento misterioso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114073.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Distintivo desgastado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112125.png","cantidad":8},{"nombre":"Destello de la noche escarchada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112128.png","cantidad":12},{"nombre":"Réplica del instrumento misterioso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114074.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Distintivo sofisticado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112126.png","cantidad":6},{"nombre":"Resplandor de la noche escarchada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112129.png","cantidad":6},{"nombre":"Réplica del instrumento misterioso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114074.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Distintivo sofisticado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112126.png","cantidad":9},{"nombre":"Resplandor de la noche escarchada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112129.png","cantidad":12},{"nombre":"Legado del instrumento misterioso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114075.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Distintivo escarchado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112127.png","cantidad":6},{"nombre":"Fulgor de la noche escarchada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112130.png","cantidad":9},{"nombre":"Legado del instrumento misterioso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114075.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Distintivo escarchado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112127.png","cantidad":12},{"nombre":"Fulgor de la noche escarchada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112130.png","cantidad":18},{"nombre":"Aspiración del instrumento misterioso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114076.png","cantidad":4}]}]'::jsonb, 'Wriothesley, Trotamundos (Wanderer), Neuvillette, Nefer y Klee.', '[{"id":"gi-wriothesley","grupo":"lista"},{"id":"gi-wanderer","grupo":"lista"},{"id":"gi-neuvillette","grupo":"lista"},{"id":"gi-nefer","grupo":"lista"},{"id":"gi-klee","grupo":"lista"}]'::jsonb),
  ('gi-w-14514', 'genshin-impact', 'Escrituras del Fluir Sempiterno', 'Tome of the Eternal Flow', '5', 'Catalizador', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Catalyst_Iudex.png', 'Un libro de enseñanzas que durante un tiempo pasó de generación en generación en un monasterio. Ya nadie sabe de su existencia.', null, 542, null, 'Daño CRIT', '88,2%', 'Oleada sempiterna', '["Otorga un 16% más de Vida. Cuando la Vida aumenta o disminuye, el daño de los Ataques Cargados aumenta en un 14%. Este efecto dura 4 s, puede acumularse hasta 3 veces y solo se puede activar una vez cada 0.3 s. Al alcanzar 3 acumulaciones o al reiniciar su duración, regenera 8 pts. de Energía Elemental. Solo se puede regenerar Energía Elemental una vez cada 12 s de esta forma.","Otorga un 20% más de Vida. Cuando la Vida aumenta o disminuye, el daño de los Ataques Cargados aumenta en un 18%. Este efecto dura 4 s, puede acumularse hasta 3 veces y solo se puede activar una vez cada 0.3 s. Al alcanzar 3 acumulaciones o al reiniciar su duración, regenera 9 pts. de Energía Elemental. Solo se puede regenerar Energía Elemental una vez cada 12 s de esta forma.","Otorga un 24% más de Vida. Cuando la Vida aumenta o disminuye, el daño de los Ataques Cargados aumenta en un 22%. Este efecto dura 4 s, puede acumularse hasta 3 veces y solo se puede activar una vez cada 0.3 s. Al alcanzar 3 acumulaciones o al reiniciar su duración, regenera 10 pts. de Energía Elemental. Solo se puede regenerar Energía Elemental una vez cada 12 s de esta forma.","Otorga un 28% más de Vida. Cuando la Vida aumenta o disminuye, el daño de los Ataques Cargados aumenta en un 26%. Este efecto dura 4 s, puede acumularse hasta 3 veces y solo se puede activar una vez cada 0.3 s. Al alcanzar 3 acumulaciones o al reiniciar su duración, regenera 11 pts. de Energía Elemental. Solo se puede regenerar Energía Elemental una vez cada 12 s de esta forma.","Otorga un 32% más de Vida. Cuando la Vida aumenta o disminuye, el daño de los Ataques Cargados aumenta en un 30%. Este efecto dura 4 s, puede acumularse hasta 3 veces y solo se puede activar una vez cada 0.3 s. Al alcanzar 3 acumulaciones o al reiniciar su duración, regenera 12 pts. de Energía Elemental. Solo se puede regenerar Energía Elemental una vez cada 12 s de esta forma."]'::jsonb, 'Tirando en el banner de armas del evento, mientras sale destacada', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Engranaje de malla","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112083.png","cantidad":3},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","cantidad":5},{"nombre":"Sedimento de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114053.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Engranaje de malla","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112083.png","cantidad":12},{"nombre":"Núcleo de la fisura","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112089.png","cantidad":18},{"nombre":"Sublimación de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114054.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Mecaengranaje recto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112084.png","cantidad":9},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","cantidad":9},{"nombre":"Sublimación de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114054.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Mecaengranaje recto","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112084.png","cantidad":14},{"nombre":"Sinapsis extrínseca","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112090.png","cantidad":18},{"nombre":"Manantial de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114055.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Engranaje mecadinámico","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112085.png","cantidad":9},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","cantidad":14},{"nombre":"Manantial de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114055.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Engranaje mecadinámico","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112085.png","cantidad":18},{"nombre":"Núcleo vital de otro mundo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112091.png","cantidad":27},{"nombre":"Esencia de rocío sagrado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114056.png","cantidad":6}]}]'::jsonb, 'Sobre todo para Neuvillette.', '[{"id":"gi-neuvillette","grupo":"destacado"}]'::jsonb),
  ('gi-w-11414', 'genshin-impact', 'Espada Amenoma Gemela', 'Amenoma Kageuchi', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Bakufu.png', 'Una espada que, según la leyenda, fue forjada a medida bajo petición de un famoso samurái que podía incluso clavársela en el aire a un guerrero tengu, conocidos por ser extremadamente veloces.', null, 454, null, 'ATQ', '55,1%', 'Legado Iwakura', '["Al lanzar una Habilidad Elemental, el personaje obtiene una semilla de la sucesión. Este efecto puede activarse como máximo una vez cada 5 s, dura 30 s y pueden poseerse 3 semillas de la sucesión al mismo tiempo. Al lanzar una Habilidad Definitiva, se consumirán todas las semillas disponibles y, 2 s después, el personaje que lleva esta arma equipada regenerará 6 pts. de Energía Elemental por cada semilla consumida.","Al lanzar una Habilidad Elemental, el personaje obtiene una semilla de la sucesión. Este efecto puede activarse como máximo una vez cada 5 s, dura 30 s y pueden poseerse 3 semillas de la sucesión al mismo tiempo. Al lanzar una Habilidad Definitiva, se consumirán todas las semillas disponibles y, 2 s después, el personaje que lleva esta arma equipada regenerará 7.5 pts. de Energía Elemental por cada semilla consumida.","Al lanzar una Habilidad Elemental, el personaje obtiene una semilla de la sucesión. Este efecto puede activarse como máximo una vez cada 5 s, dura 30 s y pueden poseerse 3 semillas de la sucesión al mismo tiempo. Al lanzar una Habilidad Definitiva, se consumirán todas las semillas disponibles y, 2 s después, el personaje que lleva esta arma equipada regenerará 9 pts. de Energía Elemental por cada semilla consumida.","Al lanzar una Habilidad Elemental, el personaje obtiene una semilla de la sucesión. Este efecto puede activarse como máximo una vez cada 5 s, dura 30 s y pueden poseerse 3 semillas de la sucesión al mismo tiempo. Al lanzar una Habilidad Definitiva, se consumirán todas las semillas disponibles y, 2 s después, el personaje que lleva esta arma equipada regenerará 10.5 pts. de Energía Elemental por cada semilla consumida.","Al lanzar una Habilidad Elemental, el personaje obtiene una semilla de la sucesión. Este efecto puede activarse como máximo una vez cada 5 s, dura 30 s y pueden poseerse 3 semillas de la sucesión al mismo tiempo. Al lanzar una Habilidad Definitiva, se consumirán todas las semillas disponibles y, 2 s después, el personaje que lleva esta arma equipada regenerará 12 pts. de Energía Elemental por cada semilla consumida."]'::jsonb, 'Forja: se fabrica en el herrero con su plano', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":2},{"nombre":"Engranaje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112047.png","cantidad":3},{"nombre":"Rama de coral del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114025.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Guardamano viejo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112044.png","cantidad":8},{"nombre":"Engranaje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112047.png","cantidad":12},{"nombre":"Rama enjoyada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114026.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":6},{"nombre":"Eje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112048.png","cantidad":6},{"nombre":"Rama enjoyada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114026.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Guardamano gemelo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112045.png","cantidad":9},{"nombre":"Eje del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112048.png","cantidad":12},{"nombre":"Rama de jade del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114027.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":6},{"nombre":"Ojo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112049.png","cantidad":9},{"nombre":"Rama de jade del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114027.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Guardamano célebre","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112046.png","cantidad":12},{"nombre":"Ojo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112049.png","cantidad":18},{"nombre":"Rama dorada del mar distante","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114028.png","cantidad":4}]}]'::jsonb, 'Kamisato Ayaka, Kamisato Ayato, Jean, Keqing, Qiqi, Viajero (Traveler), Kaeya y Xingchiu (Xingqiu).', '[{"id":"gi-ayaka","grupo":"lista"},{"id":"gi-ayato","grupo":"lista"},{"id":"gi-jean","grupo":"lista"},{"id":"gi-keqing","grupo":"lista"},{"id":"gi-qiqi","grupo":"lista"},{"id":"gi-traveler","grupo":"lista"},{"id":"gi-kaeya","grupo":"lista"},{"id":"gi-xingqiu","grupo":"lista"}]'::jsonb),
  ('gi-w-11428', 'genshin-impact', 'Espada Cruz de los Narcisos', 'Sword of Narzissenkreuz', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Purewill.png', 'Una espada cuyo poder y determinación desaparecieron cuando la historia que había detrás de ella terminó, y que ahora volverá a emprender un nuevo camino. Los resquicios de poder que aún conserva conmemoran cierto gran sueño.', null, 510, null, 'ATQ', '41,3%', 'Espada de los héroes', '["Si el portador de esta arma no tiene arjé y golpea a un enemigo con un Ataque Normal, Cargado o Descendente, liberará una explosión de energía pneuma u ousía que inflige daño equivalente al 160% de su ATQ. Este efecto solo se puede activar una vez cada 12 s, y el tipo de explosión de energía dependerá de si el tipo de energía actual de la Espada Cruz de los Narcisos es pneuma u ousía.","Si el portador de esta arma no tiene arjé y golpea a un enemigo con un Ataque Normal, Cargado o Descendente, liberará una explosión de energía pneuma u ousía que inflige daño equivalente al 200% de su ATQ. Este efecto solo se puede activar una vez cada 12 s, y el tipo de explosión de energía dependerá de si el tipo de energía actual de la Espada Cruz de los Narcisos es pneuma u ousía.","Si el portador de esta arma no tiene arjé y golpea a un enemigo con un Ataque Normal, Cargado o Descendente, liberará una explosión de energía pneuma u ousía que inflige daño equivalente al 240% de su ATQ. Este efecto solo se puede activar una vez cada 12 s, y el tipo de explosión de energía dependerá de si el tipo de energía actual de la Espada Cruz de los Narcisos es pneuma u ousía.","Si el portador de esta arma no tiene arjé y golpea a un enemigo con un Ataque Normal, Cargado o Descendente, liberará una explosión de energía pneuma u ousía que inflige daño equivalente al 280% de su ATQ. Este efecto solo se puede activar una vez cada 12 s, y el tipo de explosión de energía dependerá de si el tipo de energía actual de la Espada Cruz de los Narcisos es pneuma u ousía.","Si el portador de esta arma no tiene arjé y golpea a un enemigo con un Ataque Normal, Cargado o Descendente, liberará una explosión de energía pneuma u ousía que inflige daño equivalente al 320% de su ATQ. Este efecto solo se puede activar una vez cada 12 s, y el tipo de explosión de energía dependerá de si el tipo de energía actual de la Espada Cruz de los Narcisos es pneuma u ousía."]'::jsonb, 'Recompensa de la misión «Rowboat''s Wake»', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112080.png","cantidad":2},{"nombre":"Reloj de bolsillo vetusto de Senescal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112092.png","cantidad":3},{"nombre":"Fragmento de serenata arcaica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114049.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Condensado extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112080.png","cantidad":8},{"nombre":"Reloj de bolsillo vetusto de Senescal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112092.png","cantidad":12},{"nombre":"Pieza de serenata arcaica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114050.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Fragmento extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112081.png","cantidad":6},{"nombre":"Reloj de bolsillo estándar de Senescal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112093.png","cantidad":6},{"nombre":"Pieza de serenata arcaica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114050.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Fragmento extramarino","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112081.png","cantidad":9},{"nombre":"Reloj de bolsillo estándar de Senescal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112093.png","cantidad":12},{"nombre":"Movimiento de serenata arcaica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114051.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Cristalización cromática","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112082.png","cantidad":6},{"nombre":"Asiduidad de Senescal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112094.png","cantidad":9},{"nombre":"Movimiento de serenata arcaica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114051.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Cristalización cromática","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112082.png","cantidad":12},{"nombre":"Asiduidad de Senescal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112094.png","cantidad":18},{"nombre":"Reverberación de serenata arcaica","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114052.png","cantidad":4}]}]'::jsonb, 'Kamisato Ayaka, Kamisato Ayato, Jean, Kaedehara Kazuha, Qiqi, Viajero (Traveler), Bennett, Kaeya y Xingchiu (Xingqiu).', '[{"id":"gi-ayaka","grupo":"lista"},{"id":"gi-ayato","grupo":"lista"},{"id":"gi-jean","grupo":"lista"},{"id":"gi-kazuha","grupo":"lista"},{"id":"gi-qiqi","grupo":"lista"},{"id":"gi-traveler","grupo":"lista"},{"id":"gi-bennett","grupo":"lista"},{"id":"gi-kaeya","grupo":"lista"},{"id":"gi-xingqiu","grupo":"lista"}]'::jsonb),
  ('gi-w-11401', 'genshin-impact', 'Espada de Favonius', 'Favonius Sword', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Zephyrus.png', 'Una espada larga estándar de los Caballeros de Favonius. ¡Canalizar el poder de los elementos nunca fue tan fácil como con esta espada!', null, 454, null, 'Recarga de Energía', '61,3%', 'Avanza con el viento', '["Los Golpes CRIT tienen un 60% de probabilidad de generar una pequeña cantidad de partículas elementales, las cuales regenerarán 6 pts. de Energía para el personaje. Solo puede ocurrir una vez cada 12 s.","Los Golpes CRIT tienen un 70% de probabilidad de generar una pequeña cantidad de partículas elementales, las cuales regenerarán 6 pts. de Energía para el personaje. Solo puede ocurrir una vez cada 10.5 s.","Los Golpes CRIT tienen un 80% de probabilidad de generar una pequeña cantidad de partículas elementales, las cuales regenerarán 6 pts. de Energía para el personaje. Solo puede ocurrir una vez cada 9 s.","Los Golpes CRIT tienen un 90% de probabilidad de generar una pequeña cantidad de partículas elementales, las cuales regenerarán 6 pts. de Energía para el personaje. Solo puede ocurrir una vez cada 7.5 s.","Los Golpes CRIT tienen un 100% de probabilidad de generar una pequeña cantidad de partículas elementales, las cuales regenerarán 6 pts. de Energía para el personaje. Solo puede ocurrir una vez cada 6 s."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de evento', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","cantidad":2},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","cantidad":3},{"nombre":"Fragmento de azulejo de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114001.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_It