  ('gi-w-12303', 'genshin-impact', 'Espada de Hierro Blanco', 'White Iron Greatsword', '3', 'Mandoble', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Claymore_Tin.png', 'Un mandoble fabricado con hierro blanco que aumenta su potencia al tiempo que tiene un peso relativamente ligero. Puede ser manejada por personas con fuerza normal en los brazos, pero su manejo es mucho mejor cuando es empuñada por grandes guerreros.', null, 401, null, 'DEF', '43,9%', 'Cosecha', '["Restaura un 8% de Vida tras derrotar a un enemigo.","Restaura un 10% de Vida tras derrotar a un enemigo.","Restaura un 12% de Vida tras derrotar a un enemigo.","Restaura un 14% de Vida tras derrotar a un enemigo.","Restaura un 16% de Vida tras derrotar a un enemigo."]'::jsonb, 'Se encuentra en cofres de Mondstadt', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":1},{"nombre":"Dispositivo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112023.png","cantidad":2},{"nombre":"Grilletes de Diente de León","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114009.png","cantidad":2}]},{"desde":40,"hasta":50,"creditos":10000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":5},{"nombre":"Dispositivo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112023.png","cantidad":8},{"nombre":"Cadena de Diente de León","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114010.png","cantidad":2}]},{"desde":50,"hasta":60,"creditos":15000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","cantidad":4},{"nombre":"Circuito del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112024.png","cantidad":4},{"nombre":"Cadena de Diente de León","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114010.png","cantidad":4}]},{"desde":60,"hasta":70,"creditos":20000,"m