  ('gi-w-11302', 'genshin-impact', 'Espada del Alba', 'Harbinger of Dawn', '3', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Dawn.png', 'Una espada que solía brillar como el sol. Su portador será bendecido con una sensación de poder y bienestar. El material reflectante de su hoja se desgastó hace mucho tiempo.', null, 401, null, 'Daño CRIT', '46,9%', 'Vigor', '["Cuando la Vida esté por encima del 90%, aumenta la Prob. CRIT en un 14%.","Cuando la Vida esté por encima del 90%, aumenta la Prob. CRIT un 17.5%.","Cuando la Vida esté por encima del 90%, aumenta la Prob. CRIT un 21%.","Cuando la Vida esté por encima del 90%, aumenta la Prob. CRIT un 24.5%.","Cuando la Vida esté por encima del 90%, aumenta la Prob. CRIT un 28%."]'::jsonb, 'Tirando en el banner permanente · Tirando en los banners de evento', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":1},{"nombre":"Rama seca de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112020.png","cantidad":2},{"nombre":"Diente de leche de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114005.png","cantidad":2}]},{"desde":40,"hasta":50,"creditos":10000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":5},{"nombre":"Rama seca de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112020.png","cantidad":8},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114006.png","cantidad":2}]},{"desde":50,"hasta":60,"creditos":15000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","cantidad":4},{"nombre":"Hojas secas de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112021.png","cantidad":4},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_1