idad":12},{"nombre":"Fragmento de sueño de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114004.png","cantidad":4}]}]'::jsonb, 'Dehya, Beidou y Dori.', '[{"id":"gi-dehya","grupo":"lista"},{"id":"gi-beidou","grupo":"lista"},{"id":"gi-dori","grupo":"lista"}]'::jsonb),
  ('gi-w-11303', 'genshin-impact', 'Espada del Viajero', 'Traveler''s Handy Sword', '3', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Traveler.png', 'Una práctica espada de acero que esconde en su empuñadura unas tijeras, una lupa y yesca, entre otras cosas...', null, 448, null, 'DEF', '29,3%', 'Viaje', '["Restaura un 1% de Vida al obtener un orbe o partícula elemental.","Restaura un 1.25% de Vida al obtener un orbe o partícula elemental.","Restaura un 1.5% de Vida al obtener un orbe o partícula elemental.","Restaura un 1.75% de Vida al obtener un orbe o partícula elemental.","Restaura un 2% de Vida al obtener un orbe o partícula elemental."]'::jsonb, 'Se encuentra en cofres de Mondstadt · Recompensa de la misión «Crash Course»', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":1},{"nombre":"Dispositivo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112023.png","cantidad":2},{"nombre":"Grilletes de Diente de León","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114009.png","cantidad":2}]},{"desde":40,"hasta":50,"creditos":10000,"materiales":[{"nombre":"Pergamino guía","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112008.png","cantidad":5},{"nombre":"Dispositivo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112023.png","cantidad":8},{"nombre":"Cadena de Diente de León","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114010.png","cantidad":2}]},{"desde":50,"hasta":60,"creditos":15000,"materiales":[{"nombre":"Pergamino hechizado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112009.png","cantidad":4},{"nombre":"Circuito del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112024.png","cantidad":4},{"nombre":"Cadena de Diente de León","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114010.png","cantidad":4}]},{"desde":60,"hasta":70,"creditos":20000,"materiales":[{"nombre":"Perga