  ('gi-w-11409', 'genshin-impact', 'Espada Negra', 'The Black Sword', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Bloodstained.png', 'Una espada larga oscura que ansía el conflicto y el combate. Se dice que sume a su portador en el violento deseo de mancharse de sangre en una masacre.', null, 510, null, 'Prob. CRIT', '27,6%', 'Justicia', '["Aumenta el daño de Ataque Normal y Cargado en un 20%. Además, al asestar un golpe crítico con Ataque Normal o Cargado, recuperas Vida equivalente al 60% del ATQ. Este efecto puede activarse una vez cada 5 s.","Aumenta el daño de Ataque Normal y Cargado en un 25%. Además, al asestar un golpe crítico con Ataque Normal o Cargado, recuperas Vida equivalente al 70% del ATQ. Este efecto puede activarse una vez cada 5 s.","Aumenta el daño de Ataque Normal y Cargado en un 30%. Además, al asestar un golpe crítico con Ataque Normal o Cargado, recuperas Vida equivalente al 80% del ATQ. Este efecto puede activarse una vez cada 5 s.","Aumenta el daño de Ataque Normal y Cargado en un 35%. Además, al asestar un golpe crítico con Ataque Normal o Cargado, recuperas Vida equivalente al 90% del ATQ. Este efecto puede activarse una vez cada 5 s.","Aumenta el daño de Ataque Normal y Cargado en un 40%. Además, al asestar un golpe crítico con Ataque Normal o Cargado, recuperas Vida equivalente al 100% del ATQ. Este efecto puede activarse una vez cada 5 s."]'::jsonb, 'Pase de batalla: se elige al llegar al nivel 30 del Himno Gnóstico', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":2},{"nombre":"Rama seca de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112020.png","cantidad":3},{"nombre":"Diente de leche de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114005.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Condensado de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112002.png","cantidad":8},{"nombre":"Rama seca de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112020.png","cantidad":12},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114006.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","cantidad":6},{"nombre":"Hojas secas de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112021.png","cantidad":6},{"nombre":"Diente roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114006.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Babas de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112003.png","cantidad":9},{"nombre":"Hojas secas de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112021.png","cantidad":12},{"nombre":"Colmillo roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114007.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Esencia de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112004.png","cantidad":6},{"nombre":"Brotes de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112022.png","cantidad":9},{"nombre":"Colmillo roto de lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114007.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Esencia de Slime","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112004.png","cantidad":12},{"nombre":"Brotes de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112022.png","cantidad":18},{"nombre":"Nostalgia del lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114008.png","cantidad":4}]}]'::jsonb, 'Viajero (Traveler), Kaeya, Keqing, Kamisato Ayaka, Skirk, Kamisato Ayato, Alhacén (Alhaitham) y Clorinde.', '[{"id":"gi-traveler","grupo":"lista"},{"id":"gi-kaeya","grupo":"lista"},{"id":"gi-keqing","grupo":"lista"},{"id":"gi-ayaka","grupo":"lista"},{"id":"gi-skirk","grupo":"lista"},{"id":"gi-ayato","grupo":"lista"},{"id":"gi-alhaitham","grupo":"lista"},{"id":"gi-clorinde","grupo":"lista"}]'::jsonb),
  ('gi-w-11201', 'genshin-impact', 'Espada Plateada', 'Silver Sword', '2', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Silver.png', 'Una espada para ahuyentar a los demonios. Todo el mundo sabe que está hecha de una aleación de plata, no de plata pura.', null, 243, null, null, null, null, null, 'Se encuentra en cofres de todo Teyvat · Recompensa por hablar con algunos personajes', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","cantidad":1},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","cantidad":1},{"nombre":"Fragmento de azulejo de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114001.png","cantidad":1}]},{"desde":40,"hasta":50,"creditos":5000,"materiales":[{"nombre":"Flecha robusta","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112011.png","cantidad":4},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","cantidad":5},{"nombre":"Escombro de la ciudad de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114002.png","cantidad":1}]},{"desde":50,"hasta":60,"creditos":10000,"materiales":[{"nombre":"Flecha afilada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","cantidad":3},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","cantidad":3},{"nombre":"Escombro de la ciudad de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114002.png","cantidad":3}]},{"desde":60,"hasta":70,"creditos":15000,"materiales":[{"nombre":"Flecha afilada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112012.png","cantidad":4},{"nombre":"Cuerno de bronce negro","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112015.png","cantidad":5},{"nombre":"Fragmento de epopeya de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114003.png","cantidad":1}]}]'::jsonb, 'Solo sirve al principio del juego, hasta que consigas un arma de 3★ o más del mismo tipo. Después úsala como material para mejorar otras armas.', null),
  ('gi-w-12417', 'genshin-impact', 'Espada Real del Bosque', 'Forest Regalia', '4', 'Mandoble', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Claymore_Arakalari.png', 'Un arma obtenida a través de una de las historias de los aranara. Tiene forma de mandoble y es capaz de aplastar a cualquier enemigo del bosque.', null, 565, null, 'Recarga de Energía', '30,6%', 'Gracia del bosque', '["Tras causar una reacción de Quemadura, Aceleración, Intensificación, Propagación, Florecimiento, Florecimiento Lunar, Sobreflorecimiento o Crepitar, se crea cerca del personaje una hoja alayavijñana que existirá durante 10 s. La Maestría Elemental del personaje que la recoja aumentará en 60 pts. durante 12 s. Solo se puede crear una hoja alayavijñana cada 20 s de esta manera. Este efecto también se puede activar cuando el personaje está en tu equipo pero no en uso, y no se puede acumular.","Tras causar una reacción de Quemadura, Aceleración, Intensificación, Propagación, Florecimiento, Florecimiento Lunar, Sobreflorecimiento o Crepitar, se crea cerca del personaje una hoja alayavijñana que existirá durante 10 s. La Maestría Elemental del personaje que la recoja aumentará en 75 pts. durante 12 s. Solo se puede crear una hoja alayavijñana cada 20 s de esta manera. Este efecto también se puede activar cuando el personaje está en tu equipo pero no en uso, y no se puede acumular.","Tras causar una reacción de Quemadura, Aceleración, Intensificación, Propagación, Florecimiento, Florecimiento Lunar, Sobreflorecimiento o Crepitar, se crea cerca del personaje una hoja alayavijñana que existirá durante 10 s. La Maestría Elemental del personaje que la recoja aumentará en 90 pts. durante 12 s. Solo se puede crear una hoja alayavijñana cada 20 s de esta manera. Este efecto también se puede activar cuando el personaje está en tu equipo pero no en uso, y no se puede acumular.","Tras causar una reacción de Quemadura, Aceleración, Intensificación, Propagación, Florecimiento, Florecimiento Lunar, Sobreflorecimiento o Crepitar, se crea cerca del personaje una hoja alayavijñana que existirá durante 10 s. La Maestría Elemental del personaje que la recoja aumentará en 105 pts. durante 12 s. Solo se puede crear una hoja alayavijñana cada 20 s de esta manera. Este efecto también se puede activar cuando el personaje está en tu equipo pero no en uso, y no se puede acumular.","Tras causar una reacción de Quemadura, Aceleración, Intensificación, Propagación, Florecimiento, Florecimiento Lunar, Sobreflorecimiento o Crepitar, se crea cerca del personaje una hoja alayavijñana que existirá durante 10 s. La Maestría Elemental del personaje que la recoja aumentará en 120 pts. durante 12 s. Solo se puede crear una hoja alayavijñana cada 20 s de esta manera. Este efecto también se puede activar cuando el personaje está en tu equipo pero no en uso, y no se puede acumular."]'::jsonb, 'Forja: se fabrica en el herrero con su plano', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Satén rojo descolorido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112065.png","cantidad":2},{"nombre":"Contenedor del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112068.png","cantidad":3},{"nombre":"Talismán de bronce del rocío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114037.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Satén rojo descolorido","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112065.png","cantidad":8},{"nombre":"Contenedor del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112068.png","cantidad":12},{"nombre":"Talismán de metal del rocío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114038.png","cantidad":3}]},{"desde":50,"hasta":60,"creditos":20000,"materiales":[{"nombre":"Seda roja bordada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112066.png","cantidad":6},{"nombre":"Módulo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112069.png","cantidad":6},{"nombre":"Talismán de metal del rocío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114038.png","cantidad":6}]},{"desde":60,"hasta":70,"creditos":30000,"materiales":[{"nombre":"Seda roja bordada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112066.png","cantidad":9},{"nombre":"Módulo del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112069.png","cantidad":12},{"nombre":"Talismán de plata del rocío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114039.png","cantidad":3}]},{"desde":70,"hasta":80,"creditos":35000,"materiales":[{"nombre":"Brocado rojo lujoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112067.png","cantidad":6},{"nombre":"Perno del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112070.png","cantidad":9},{"nombre":"Talismán de plata del rocío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114039.png","cantidad":6}]},{"desde":80,"hasta":90,"creditos":45000,"materiales":[{"nombre":"Brocado rojo lujoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112067.png","cantidad":12},{"nombre":"Perno del caos","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112070.png","cantidad":18},{"nombre":"Talismán de oro del rocío","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114040.png","cantidad":4}]}]'::jsonb, 'Sobre todo para Dori y Dehya. También va bien con Sayu y Kaveh.', '[{"id":"gi-dori","grupo":"destacado"},{"id":"gi-dehya","grupo":"destacado"},{"id":"gi-sayu","grupo":"otros"},{"id":"gi-kaveh","grupo":"otros"}]'::jsonb),
  ('gi-w-11404', 'genshin-impact', 'Espada Real Larga', 'Royal Longsword', '4', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Theocrat.png', 'Una vieja espada larga que perteneció a aquellos que una vez gobernaron sobre Mondstadt. Tiene un acabado exquisito. Sus decoraciones y grabados son una muestra del estatus de su antiguo propietario.', null, 510, null, 'ATQ', '41,3%', 'Concentración', '["Al dañar a un enemigo, aumenta la Prob. CRIT en un 8%. Puede acumularse hasta 5 veces. Una vez asestado un golpe CRIT, las acumulaciones de Concentración se reiniciarán.","Al dañar a un enemigo, aumenta la Prob. CRIT en un 10%. Puede acumularse hasta 5 veces. Una vez asestado un golpe CRIT, las acumulaciones de Concentración se reiniciarán.","Al dañar a un enemigo, aumenta la Prob. CRIT en un 12%. Puede acumularse hasta 5 veces. Una vez asestado un golpe CRIT, las acumulaciones de Concentración se reiniciarán.","Al dañar a un enemigo, aumenta la Prob. CRIT en un 14%. Puede acumularse hasta 5 veces. Una vez asestado un golpe CRIT, las acumulaciones de Concentración se reiniciarán.","Al dañar a un enemigo, aumenta la Prob. CRIT en un 16%. Puede acumularse hasta 5 veces. Una vez asestado un golpe CRIT, las acumulaciones de Concentración se reiniciarán."]'::jsonb, 'Ofertas de Paimon: se compra con Brillo estelar sin dueño', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","cantidad":2},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","cantidad":3},{"nombre":"Fragmento de azulejo de Decarabian","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114001.png","cantidad":3}]},{"desde":40,"hasta":50,"creditos":15000,"materiales":[{"nombre":"Máscara dañada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112005.png","cantidad":8},{"nombre":"Cuerno pesado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112014.png","cantid