i.yatta.moe/assets/UI/UI_ItemIcon_112004.png","cantidad":18},{"nombre":"Brotes de líneas ley","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112022.png","cantidad":27},{"nombre":"Nostalgia del lobo boreal","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114008.png","cantidad":6}]}]'::jsonb, 'Sobre todo para Jean, Kaeya, Bennett, Kaedehara Kazuha y Furina. También va bien con Viajero (Traveler), Xingchiu (Xingqiu), Qiqi, Lynette, Kamisato Ayato, Laila (Layla), Xilonen y Dahlia.', '[{"id":"gi-jean","grupo":"destacado"},{"id":"gi-kaeya","grupo":"destacado"},{"id":"gi-bennett","grupo":"destacado"},{"id":"gi-kazuha","grupo":"destacado"},{"id":"gi-furina","grupo":"destacado"},{"id":"gi-traveler","grupo":"otros"},{"id":"gi-xingqiu","grupo":"otros"},{"id":"gi-qiqi","grupo":"otros"},{"id":"gi-lynette","grupo":"otros"},{"id":"gi-ayato","grupo":"otros"},{"id":"gi-layla","grupo":"otros"},{"id":"gi-xilonen","grupo":"otros"},{"id":"gi-dahlia","grupo":"otros"}]'::jsonb),
  ('gi-w-11521', 'genshin-impact', 'Hoja de Exáifanes', 'Exaiphanes Blade', '5', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_WeaponQuestSnezhnaya.png', 'Una espada larga que alguna vez brilló con la gloriosa luz de la Estrella Albina. Al caer en manos de alguien que ha emprendido un viaje, se ha convertido en un resplandor completamente nuevo que no pertenece a ninguna época pasada.', null, 608, null, 'Prob. CRIT', '33,1%', 'Senda del viajero', '["Cuando {F#la Viajera}{M#el Viajero} lleva esta arma equipada, tras golpear a un enemigo, su ATQ aumenta en un 16% durante 8 s y recupera 3 pts. de Energía Elemental. Este efecto solo puede ocurrir una vez cada 5 s y se puede activar incluso cuando el personaje está en tu equipo pero no en uso.","Cuando {F#la Viajera}{M#el Viajero} lleva esta arma equipada, su Daño CRIT aumenta en un 6% por cada elemento con el que haya resonado. Además, cuando {F#la Viajera}{M#el Viajero} golpea a un enemigo con un ataque, su ATQ aumenta en un 20% durante 8 s y recupera 3 pts. de Energía Elemental. Este efecto solo puede ocurrir una vez cada 5 s y se puede activar incluso cuando el personaje está en tu equipo pero no en uso.","Cuando {F#la Viajera}{M#el Viajero} lleva esta arma equipada, su Daño CRIT aumenta en un 6% por cada elemento con el que haya resonado. Además, cuando {F#la Viajera}{M#el Viajero} golpea a un enemigo con un ataque, su ATQ aumenta en un 24% durante 8 s y recupera 5 pts. de Energía Elemental. Este efecto solo puede ocurrir una vez cada 5 s y se puede activar incluso cuando el personaje está en tu equipo pero no en uso.","Cuando {F#la Viajera}{M#el Viajero} lleva esta arma equipada, su Daño CRIT aumenta en un 6% por cada elemento con el que haya resonado. Además, cuando {F#la Viajera}{M#el Viajero} golpea a un enemigo con un ataque, su ATQ aumenta en un 32% durante 8 s y recupera 5 pts. de Energía Elemental. Este efecto solo puede ocurrir una vez cada 5 s y se puede activar incluso cuando el personaje está en tu equipo pero no en uso.","Cuando {F#la Viajera}{M#el Viajero} lleva esta arma equipada, su Daño CRIT aumenta en un 6% por cada elemento con el que haya resonado. Además, cuando {F#la Viajera}{M#el Viajero} golpea a un enemigo con un ataque, su ATQ aumenta en un 40% durante 8 s y recupera 5 pts. de Energía Elemental. Este efecto solo puede ocurrir una vez cada 5 s y se puede activar incluso cuando el personaje está en tu equipo pero no en uso."]'::jsonb, 'Recompensa de la misión «Great Deeds on the Tundra»', '[{"desde":20,"hasta":40,"creditos":10000,"materiales":[{"nombre":"Lumiesquirla etérea","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112146.png","cantidad":3},{"nombre":"Fragmento sedimentado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112152.png","cantidad":5},{"nombre":"Renacimiento del emperador de la escarcha","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114093.png","cantidad":5}]},{"desde":40,"hasta":50,"creditos":20000,"materiales":[{"nombre":"Lumiesquirla etérea","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112146.png","cantidad":12},{"nombre":"Fragmento sedimentado","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112152.png","cantidad":18},{"nombre":"Ceremonia del emperador de la escarcha","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114094.png","cantidad":5}]},{"desde":50,"hasta":60,"creditos":30000,"materiales":[{"nombre":"Quiebracristal etéreo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112147.png","cantidad":9},{"nombre":"Masa sedimentada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112153.png","cantidad":9},{"nombre":"Ceremonia del emperador de la escarcha","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114094.png","cantidad":9}]},{"desde":60,"hasta":70,"creditos":45000,"materiales":[{"nombre":"Quiebracristal etéreo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112147.png","cantidad":14},{"nombre":"Masa sedimentada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112153.png","cantidad":18},{"nombre":"Compasión del emperador de la escarcha","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114095.png","cantidad":5}]},{"desde":70,"hasta":80,"creditos":55000,"materiales":[{"nombre":"Petreoescama etérea","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112148.png","cantidad":9},{"nombre":"Acreción sedimentada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112154.png","cantidad":14},{"nombre":"Compasión del emperador de la escarcha","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114095.png","cantidad":9}]},{"desde":80,"hasta":90,"creditos":65000,"materiales":[{"nombre":"Petreoescama etérea","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112148.png","cantidad":18},{"nombre":"Acreción sedimentada","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112154.png","cantidad":27},{"nombre":"Adiós del emperador de la escarcha","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114096.png","cantidad":6}]}]'::jsonb, 'Viajero (Traveler).', '[{"id":"gi-traveler","grupo":"lista"}]'::jsonb),
  ('gi-w-11305', 'genshin-impact', 'Hoja de Filetear', 'Fillet Blade', '3', 'Espada ligera', 'https://gi.yatta.moe/assets/UI/UI_EquipIcon_Sword_Sashimi.png', 'Un cuchillo afilado con una larga hoja.', null, 401, null, 'ATQ', '35,2%', 'Determinación', '["Al golpear a un enemigo con un ataque, hay un 50% de probabilidad de infligir un 240% de daño a un solo enemigo. Este efecto puede ocurrir una vez cada 15 s.","Al golpear a un enemigo con un ataque, hay un 50% de probabilidad de infligir un 280% de daño a un solo enemigo. Este efecto puede ocurrir una vez cada 14 s.","Al golpear a un enemigo con un ataque, hay un 50% de probabilidad de infligir un 320% de daño a un solo enemigo. Este efecto puede ocurrir una vez cada 13 s.","Al golpear a un enemigo con un ataque, hay un 50% de probabilidad de infligir un 360% de daño a un solo enemigo. Este efecto puede ocurrir una vez cada 12 s.","Al golpear a un enemigo con un ataque, hay un 50% de probabilidad de infligir un 400% de daño a un solo enemigo. Este efecto puede ocurrir una vez cada 11 s."]'::jsonb, 'Se encuentra en cofres de Liyue · Recompensa por hablar con algunos personajes', '[{"desde":20,"hasta":40,"creditos":5000,"materiales":[{"nombre":"Polen neblinoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112026.png","cantidad":2},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","cantidad":1},{"nombre":"Perdigones de plomo","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114017.png","cantidad":2}]},{"desde":40,"hasta":50,"creditos":10000,"materiales":[{"nombre":"Polen neblinoso","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112026.png","cantidad":8},{"nombre":"Insignia de cuervo de bronce","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_112035.png","cantidad":5},{"nombre":"Perdigones de mercurio","icono":"https://gi.yatta.moe/assets/UI/UI_ItemIcon_114018.png","cantidad":2}]},{"desde":50,"hasta":60,"creditos":15000,"materiales":[{"nombre":"Hier